def choose_move(observation):
    def p(v, d=(0, 0)):
        try:
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return int(v[0]), int(v[1])
        except:
            pass
        return d

    def sgn(x):
        return -1 if x < 0 else (1 if x > 0 else 0)

    def man(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def add(a, d):
        return (a[0] + d[0], a[1] + d[1])

    me = p(observation.get("self_position"))
    opp = p(observation.get("opponent_position"), me)

    obs = set()
    for q in observation.get("obstacles") or []:
        obs.add(p(q))

    resources = []
    for q in observation.get("resources") or []:
        if isinstance(q, dict):
            q = q.get("position", q.get("pos", q.get("location", q)))
        resources.append(p(q))

    targets = []
    for key in ("territory", "frontier", "goals", "targets", "cells"):
        for q in observation.get(key) or []:
            if isinstance(q, dict):
                q = q.get("position", q.get("pos", q.get("location", q)))
            targets.append(p(q))

    def legal(d):
        return add(me, d) not in obs

    def choose_best(cands, focus=None, flee=None):
        best = None
        bestv = None
        for d in cands:
            if not legal(d):
                continue
            np = add(me, d)
            v = ()
            if focus is not None:
                v += (man(np, focus),)
            if flee is not None:
                v += (man(np, flee),)
            v += (-abs(d[0]) - abs(d[1]), -d[0], -d[1])
            if bestv is None or v < bestv:
                bestv = v
                best = [d[0], d[1]]
        return best

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)]

    if resources:
        t = min(resources, key=lambda r: (man(me, r), man(opp, r), r[0], r[1]))
        d = choose_best(dirs, focus=t, flee=opp)
        if d is not None:
            return d

    if targets:
        t = min(targets, key=lambda r: (man(me, r), man(opp, r), r[0], r[1]))
        d = choose_best(dirs, focus=t, flee=opp)
        if d is not None:
            return d

    dist = man(me, opp)
    if dist <= 2:
        cand = []
        for d in dirs:
            if legal(d):
                np = add(me, d)
                cand.append((man(np, opp), -abs(d[0]) - abs(d[1]), d))
        if cand:
            cand.sort()
            d = cand[-1][2]
            return [d[0], d[1]]

    if dist >= 3:
        d = [sgn(opp[0] - me[0]), sgn(opp[1] - me[1])]
        if legal((d[0], d[1])):
            return d

    for d in [(1, 0), (0, 1), (-1, 0), (0, -1), (0, 0)]:
        if legal(d):
            return [d[0], d[1]]

    return [0, 0]

